  //   console.log('🚀 ~ getProTokenList ~ res1:', res1)
  //   console.log('🚀 ~ getProTokenList ~ params:', params)
  //   const res = await getStatesTokens(params)
  //   console.log('🚀 ~ getProTokenList ~ res:', res)
  //   const coinTypesObj: any = {}

  //   res?.data?.forEach((item: any) => {
  //     coinTypesObj[item?.coinType] = true
  //   })
  //   const coinTypes: any = Object.keys(coinTypesObj)
  //   // console.log('🚀 ~ getProTokenList ~ coinTypes:', coinTypes)
  //   const relatedTokenMap = await getTokenInfos(coinTypes)
  //   // console.log('🚀 ~ getProTokenList ~ relatedTokenMap:', relatedTokenMap)
  //   const data = res?.data?.map((item: any) => {
  //     coinTypesObj[item?.coinType] = true
